fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Number of input rows
    let rows = x.len();
    // Number of columns in each row (all same length by problem statement)
    let cols = x[0].len();

    // Initialize the result matrix with dimensions cols x rows
    // Using vec![vec![0.0; rows]; cols] is ok since f32: Copy
    let mut result = vec![vec![0.0; rows]; cols];

    // For every element, swap row and column indices to transpose
    for r in 0..rows {
        for c in 0..cols {
            result[c][r] = x[r][c];
        }
    }

    result
}